#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [prefix x | middle | suffix y] -> [suffix | middle | prefix]
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n - 2; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed + 1){ pos = i; break; }
        if(pos == placed) continue;

        // Step 1: Move element from pos to position n-1
        if(pos != n - 1){
            // We want to use x = pos+1, y = n-1-pos
            // But x+y = pos+1+n-1-pos = n, need < n
            // So use x = pos, y = n-1-pos when pos > 0
            // After: [suffix(n-1-pos) | middle(1 elem at pos) | prefix(pos)]
            // Element at pos goes to position n-1-pos (it's the single middle element)
            // Actually let's think differently: just get it to last position

            // Use x=pos+1, y=n-1-pos-1 = n-pos-2 if valid (middle has 1 elem)
            // x+y = pos+1+n-pos-2 = n-1 < n. Valid if y>0 => n-pos-2>0 => pos<n-2
            if(pos < n - 2){
                int x = pos + 1, y = n - pos - 2;
                ops.push_back({x, y});
                apply(p, x, y);
                // element was at pos, now it's at: suffix has y elems, middle has 1 elem (the one at index pos+1..n-1-y = x..n-1-y)
                // Actually element at index pos is in prefix. Prefix goes to end.
                // New position = y + (n-x-y) + (pos) = y + 1 + pos... let me just search
                for(int i = 0; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
            } else {
                // pos == n-2, use x=1, y=1, moves last to front, first to end
                // element at n-2 goes to middle position n-2-1? Just do it and search
                ops.push_back({1, 1});
                apply(p, 1, 1);
                for(int i = 0; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
                if(pos != n-1) continue; // bail
            }
        }
        if(pos != n-1) { // retry finding
            for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if(pos==placed) continue;
            if(pos!=n-1) continue;
        }
        // Step 2: element at n-1, move to position placed
        // x=placed+1, y=1, x+y=placed+2 < n when placed < n-2 (true)
        if(placed + 2 <= n - 1){
            ops.push_back({placed + 1, 1});
            apply(p, placed + 1, 1);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
